def verify(f,dur,frames):
 q=json.loads(subprocess.check_output(['ffprobe','-v','error','-count_frames','-show_streams','-show_format','-of','json',str(f)]));v=next(x for x in q['streams']if x['codec_type']=='video');assert(v['width'],v['height'],v['r_frame_rate'],int(v['nb_read_frames']))==(1080,1920,'24/1',frames);assert abs(float(q['format']['duration'])-dur)<.003;assert any(x['codec_type']=='audio'for x in q['streams']);subprocess.run(['ffmpeg','-v','error','-xerror','-i',str(f),'-f','null','-'],check=True);return q
probe=verify(F,D,D*fps);assert F.stat().st_size<95*1024*1024;(P/'qa/ffprobe-final.json').write_text(json.dumps(probe,indent=2))
r=subprocess.run(['ffmpeg','-hide_banner','-i',str(F),'-vn','-af','ebur128=peak=true','-f','null','-'],capture_output=True,text=True,check=True).stderr;r=r[r.rfind('Summary:'):];lufs=float(re.search(r'I:\s*([-\d.]+) LUFS',r).group(1));peak=float(re.search(r'Peak:\s*([-\d.]+) dBFS',r).group(1));assert -25<lufs< -15 and peak< -2,(lufs,peak);(P/'qa/final-audio-validation.json').write_text(json.dumps({'integrated_lufs':lufs,'true_peak_dbfs':peak,'clipping_detected':False,'same_voice':'Puck/gemini-2.5-flash-preview-tts','speed_change':False,'human_full_listening':False,'asr':'final-narration-check.json'if C['theme']==41 else 'narration-check.json'},indent=2))
shots=json.loads((P/'story/shots.json').read_text())['shots'];times=[(s['start']+s['end'])/2 for s in shots]+[16.5,20.5,38.5,42.5];im=Image.new('RGB',(1040,((len(times)+3)//4)*490),'#13273e');d=ImageDraw.Draw(im)
for i,t in enumerate(times):
 f=W/f'final-{i:02}.jpg';subprocess.run(['ffmpeg','-v','error','-y','-ss',str(t),'-i',str(F),'-frames:v','1','-vf','scale=250:444',str(f)],check=True);x=i%4*260+5;y=i//4*490;im.paste(Image.open(f),(x,y+28));d.text((x,y+5),f'{t:.2f}s',fill='white')
im.save(P/'qa/filme-completo.jpg',quality=92)
preview=P/'exports/preview-12s.mp4';subprocess.run(['ffmpeg','-v','error','-y','-ss','12','-i',str(F),'-t','12','-c:v','libx264','-threads','2','-preset','fast','-crf','20','-c:a','aac','-b:a','192k','-movflags','+faststart',str(preview)],check=True);verify(preview,12,288)
